package com.omoda5.demo

import android.content.Context
import android.media.MediaPlayer
import android.media.MediaRecorder
import android.os.Build
import android.speech.tts.TextToSpeech
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import okhttp3.*
import okhttp3.MediaType.Companion.toMediaTypeOrNull
import okhttp3.RequestBody.Companion.asRequestBody
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.util.Locale

class OpenAIManager(
    private val context: Context,
    private val onStateChanged: (String) -> Unit,
    private val onResultCallback: (String) -> Unit
) {
    private var mediaRecorder: MediaRecorder? = null
    private var mediaPlayer: MediaPlayer? = null
    var audioFile: File? = null
    private val settingsManager = SettingsManager(context)
    private val client = OkHttpClient()

    private var textToSpeech: TextToSpeech? = null
    private var voskManager: VoskManager? = null

    private var edgeTtsManager: EdgeTtsManager? = null

    init {
        initTTS()
        initVosk()
        edgeTtsManager = EdgeTtsManager(client)
    }

    private fun initTTS() {
        textToSpeech = TextToSpeech(context) { status ->
            if (status == TextToSpeech.SUCCESS) {
                textToSpeech?.language = Locale("tr", "TR")
            }
        }
    }

    private fun initVosk() {
        voskManager = VoskManager(context, onStateChanged)
        voskManager?.initModel {
            // Model yüklendi
        }
    }

    fun startRecording() {
        try {
            audioFile = File(context.cacheDir, "temp_audio.wav")
            mediaRecorder = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
                MediaRecorder(context)
            } else {
                @Suppress("DEPRECATION")
                MediaRecorder()
            }.apply {
                setAudioSource(MediaRecorder.AudioSource.VOICE_RECOGNITION)
                setOutputFormat(MediaRecorder.OutputFormat.DEFAULT) // PCM WAV tarzı
                setAudioEncoder(MediaRecorder.AudioEncoder.DEFAULT)
                setOutputFile(audioFile?.absolutePath)
                prepare()
                start()
            }
            onStateChanged("DİNLENİYOR...")
        } catch (e: Exception) {
            e.printStackTrace()
            onStateChanged("KAYIT HATASI: ${e.message}")
        }
    }

    fun stopRecordingAndProcess(coroutineScope: CoroutineScope) {
        try {
            mediaRecorder?.stop()
            mediaRecorder?.release()
            mediaRecorder = null
            onStateChanged("İŞLENİYOR...")

            coroutineScope.launch {
                processSTTAndLLM()
            }
        } catch (e: Exception) {
            e.printStackTrace()
            onStateChanged("KAYIT DURDURMA HATASI")
        }
    }

    fun cancelRecording() {
        try {
            mediaRecorder?.stop()
        } catch (e: Exception) {}
        try {
            mediaRecorder?.release()
        } catch (e: Exception) {}
        mediaRecorder = null

        audioFile?.let {
            if (it.exists()) it.delete()
        }
        onStateChanged("İPTAL EDİLDİ")

        // Biraz bekleyip hazır durumuna dön
        CoroutineScope(Dispatchers.Main).launch {
            kotlinx.coroutines.delay(1000)
            onStateChanged("HAZIR")
        }
    }

    private suspend fun processSTTAndLLM() {
        val file = audioFile
        if (file == null || !file.exists()) {
            withContext(Dispatchers.Main) { onStateChanged("Ses dosyası bulunamadı") }
            return
        }

        val engine = settingsManager.sttEngine
        var recognizedText = ""

        if (engine == "VOSK" && voskManager?.isInitialized == true) {
            withContext(Dispatchers.Main) { onStateChanged("VOSK İLE ÇEVRİLİYOR...") }
            recognizedText = voskManager?.recognizeAudioFile(file) ?: ""
        } else {
            // HERMES veya diğer REST API STT
            withContext(Dispatchers.Main) { onStateChanged("HERMES İLE ÇEVRİLİYOR...") }
            try {
                val requestBody = MultipartBody.Builder()
                    .setType(MultipartBody.FORM)
                    .addFormDataPart("file", file.name, file.asRequestBody("audio/wav".toMediaTypeOrNull()))
                    .addFormDataPart("model", "ipisper-large-v3-turbo")
                    .addFormDataPart("language", "tr")
                    .build()

                val request = Request.Builder()
                    .url(settingsManager.sttUrl)
                    .addHeader("Authorization", "Bearer ${settingsManager.sttApiKey}")
                    .post(requestBody)
                    .build()

                val response = withContext(Dispatchers.IO) { client.newCall(request).execute() }
                val responseBody = response.body?.string() ?: ""

                if (response.isSuccessful) {
                    val json = JSONObject(responseBody)
                    recognizedText = json.optString("text", "")
                } else {
                    withContext(Dispatchers.Main) { onStateChanged("STT HATASI: ${response.code}") }
                    return
                }
            } catch (e: Exception) {
                e.printStackTrace()
                withContext(Dispatchers.Main) { onStateChanged("AĞ HATASI (STT): ${e.message}") }
                return
            }
        }

        if (recognizedText.isNotBlank()) {
            withContext(Dispatchers.Main) {
                onResultCallback(recognizedText)
            }

            if (engine == "VOSK") {
                if (settingsManager.isTtsReadEnabled) {
                    processTTS(recognizedText)
                } else {
                    withContext(Dispatchers.Main) { onStateChanged("HAZIR") }
                }
            } else {
                withContext(Dispatchers.Main) {
                    onStateChanged("CEVAP BEKLENİYOR...")
                }
                processLLM(recognizedText)
            }
        } else {
            withContext(Dispatchers.Main) { onStateChanged("HAZIR") }
        }
    }

    private suspend fun processLLM(userText: String) {
        try {
            val jsonBody = JSONObject().apply {
                put("model", "google/gemini-2.5-flash")
                put("messages", JSONArray().apply {
                    put(JSONObject().apply {
                        put("role", "system")
                        put("content", "Sen araç asistanısın. Kısa, net ve samimi cevaplar ver. Türkçe konuş.")
                    })
                    put(JSONObject().apply {
                        put("role", "user")
                        put("content", userText)
                    })
                })
            }

            val requestBody = jsonBody.toString().toRequestBody("application/json".toMediaTypeOrNull())
            val request = Request.Builder()
                .url(settingsManager.ttsUrl) // Reusing ttsUrl for LLM as defined in SettingsManager
                .addHeader("Authorization", "Bearer ${settingsManager.ttsApiKey}")
                .post(requestBody)
                .build()

            val response = withContext(Dispatchers.IO) { client.newCall(request).execute() }
            val responseBody = response.body?.string() ?: ""

            if (response.isSuccessful) {
                val json = JSONObject(responseBody)
                val choices = json.optJSONArray("choices")
                if (choices != null && choices.length() > 0) {
                    val message = choices.getJSONObject(0).optJSONObject("message")
                    val assistantResponse = message?.optString("content", "") ?: ""

                    withContext(Dispatchers.Main) {
                        onResultCallback(assistantResponse)
                    }

                    if (settingsManager.isTtsReadEnabled) {
                        processTTS(assistantResponse)
                    } else {
                        withContext(Dispatchers.Main) { onStateChanged("HAZIR") }
                    }
                } else {
                    withContext(Dispatchers.Main) { onStateChanged("LLM BOŞ CEVAP") }
                }
            } else {
                withContext(Dispatchers.Main) { onStateChanged("LLM HATASI: ${response.code}") }
            }
        } catch (e: Exception) {
            e.printStackTrace()
            withContext(Dispatchers.Main) { onStateChanged("AĞ HATASI (LLM): ${e.message}") }
        }
    }

    fun playTextViaTTS(text: String, scope: CoroutineScope) {
        scope.launch {
            processTTS(text)
        }
    }

    private suspend fun processTTS(text: String) {
        if (text.isBlank()) return

        if (settingsManager.ttsEngine == "EDGE") {
            withContext(Dispatchers.Main) { onStateChanged("EDGE TTS HAZIRLANIYOR...") }
            val ttsFile = File(context.cacheDir, "edge_tts.mp3")
            val success = withContext(Dispatchers.IO) {
                edgeTtsManager?.synthesizeText(text, ttsFile) ?: false
            }
            if (success && ttsFile.exists()) {
                withContext(Dispatchers.Main) {
                    onStateChanged("SES ÇALINIYOR")
                    playAudio(ttsFile.absolutePath)
                }
            } else {
                withContext(Dispatchers.Main) { onStateChanged("EDGE TTS BAŞARISIZ") }
            }
        } else {
            // Android Native TextToSpeech
            withContext(Dispatchers.Main) {
                onStateChanged("SES ÇALINIYOR")

                textToSpeech?.setOnUtteranceProgressListener(object : android.speech.tts.UtteranceProgressListener() {
                    override fun onStart(utteranceId: String?) {}
                    override fun onDone(utteranceId: String?) {
                        CoroutineScope(Dispatchers.Main).launch {
                            onStateChanged("HAZIR")
                        }
                    }
                    override fun onError(utteranceId: String?) {
                        CoroutineScope(Dispatchers.Main).launch {
                            onStateChanged("HAZIR")
                        }
                    }
                })

                val params = android.os.Bundle()
                params.putString(TextToSpeech.Engine.KEY_PARAM_UTTERANCE_ID, "tts1")
                textToSpeech?.speak(text, TextToSpeech.QUEUE_FLUSH, params, "tts1")
            }
        }
    }

    private fun playAudio(filePath: String) {
        try {
            mediaPlayer?.release()
            mediaPlayer = MediaPlayer().apply {
                setDataSource(filePath)
                prepare()
                start()
                setOnCompletionListener {
                    onStateChanged("HAZIR")
                    it.release()
                    mediaPlayer = null
                }
            }
        } catch (e: Exception) {
            e.printStackTrace()
            onStateChanged("ÇALMA HATASI")
        }
    }

    fun getMaxAmplitude(): Int {
        return try {
            mediaRecorder?.maxAmplitude ?: 0
        } catch (e: Exception) {
            0
        }
    }

    fun release() {
        mediaRecorder?.release()
        mediaRecorder = null
        mediaPlayer?.release()
        mediaPlayer = null
        textToSpeech?.shutdown()
    }
}

package com.omoda5.demo

import android.util.Log
import java.io.InputStream
import java.io.OutputStream
import java.net.InetSocketAddress
import java.net.Socket
import java.nio.ByteBuffer
import java.nio.ByteOrder

object DemoAdbClient {
    private const val A_CNXN = 0x4e584e43
    private const val A_OPEN = 0x4e45504f
    private const val A_OKAY = 0x59414b4f
    private const val A_CLSE = 0x45534c43
    private const val A_WRTE = 0x45545257
    private const val A_AUTH = 0x48545541

    fun executeCommandSync(cmd: String, onLine: (String) -> Unit) {
        try {
            var socket: Socket? = null
            var connected = false
            val hosts = arrayOf("127.0.0.1", "10.0.2.15", "0.0.0.0")

            for (h in hosts) {
                try {
                    socket = Socket()
                    socket.connect(InetSocketAddress(h, 5555), 1000)
                    connected = true
                    Log.d("DemoAdb", "Connected to ADB on $h")
                    break
                } catch (e: Exception) { 
                    socket?.close()
                    continue 
                }
            }

            if (!connected) {
                onLine("0x11600207 value: [ADB_CLOSED_FALLING_BACK]")
                val proc = Runtime.getRuntime().exec(arrayOf("sh", "-c", cmd))
                val reader = proc.inputStream.bufferedReader()
                var line: String?
                while (reader.readLine().also { line = it } != null) {
                    onLine(line!!)
                }
                proc.waitFor()
                return
            }

            val out = socket!!.getOutputStream()
            val ins = socket.getInputStream()

            sendAdbPacket(out, A_CNXN, 0x01000000, 4096, "host::\u0000")
            val resp = readAdbPacket(ins)
            if (resp.cmd == A_AUTH) { 
                onLine("0x11600207 value: [ADB_RSA_AUTH_REQUIRED]")
                return 
            }
            if (resp.cmd != A_CNXN) {
                onLine("0x11600207 value: [ADB_CNXN_FAILED]")
                throw Exception("Connect Failed")
            }

            val localId = 1
            sendAdbPacket(out, A_OPEN, localId, 0, "shell:$cmd\u0000")
            val openResp = readAdbPacket(ins)

            if (openResp.cmd == A_OKAY) {
                val remoteId = openResp.arg0
                val lineBuffer = java.lang.StringBuilder()

                while (!socket.isClosed) {
                    val pkt = readAdbPacket(ins)
                    when (pkt.cmd) {
                        A_WRTE -> {
                            pkt.data?.let {
                                lineBuffer.append(String(it))
                                var newlineIdx = lineBuffer.indexOf("\n")
                                while (newlineIdx != -1) {
                                    val line = lineBuffer.substring(0, newlineIdx).trim()
                                    lineBuffer.delete(0, newlineIdx + 1)
                                    if (line.isNotEmpty()) {
                                        onLine(line)
                                    }
                                    newlineIdx = lineBuffer.indexOf("\n")
                                }
                            }
                            sendAdbPacket(out, A_OKAY, localId, remoteId, null)
                        }
                        A_CLSE -> break
                    }
                }
                if (lineBuffer.isNotEmpty()) {
                    onLine(lineBuffer.toString().trim())
                }
            }
            socket.close()
        } catch (e: Exception) {
            onLine("0x11600207 value: [ERROR_${e.message?.replace(" ", "_")}]")
        }
    }

    private fun sendAdbPacket(out: OutputStream, cmd: Int, arg0: Int, arg1: Int, data: String?) {
        val payload = data?.toByteArray() ?: byteArrayOf()
        val length = payload.size
        val check = payload.fold(0) { acc, byte -> acc + (byte.toInt() and 0xFF) }
        val header = ByteBuffer.allocate(24).order(ByteOrder.LITTLE_ENDIAN)
        header.putInt(cmd).putInt(arg0).putInt(arg1).putInt(length).putInt(check).putInt(cmd xor -0x1)
        out.write(header.array())
        if (payload.isNotEmpty()) out.write(payload)
        out.flush()
    }

    private fun readAdbPacket(ins: InputStream): AdbPacket {
        val headerBuf = ByteArray(24)
        var total = 0
        while (total < 24) {
            val count = ins.read(headerBuf, total, 24 - total)
            if (count < 0) throw java.io.IOException("EOF")
            total += count
        }
        val buffer = ByteBuffer.wrap(headerBuf).order(ByteOrder.LITTLE_ENDIAN)
        val cmd = buffer.getInt()
        val arg0 = buffer.getInt()
        val arg1 = buffer.getInt()
        val length = buffer.getInt()
        var data: ByteArray? = null
        if (length > 0) {
            data = ByteArray(length)
            var dTotal = 0
            while (dTotal < length) {
                val dCount = ins.read(data, dTotal, length - dTotal)
                if (dCount < 0) break
                dTotal += dCount
            }
        }
        return AdbPacket(cmd, arg0, arg1, data)
    }

    private data class AdbPacket(val cmd: Int, val arg0: Int, val arg1: Int, val data: ByteArray?)
}

package com.omoda5.demo

import android.app.Service
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.graphics.PixelFormat
import android.media.AudioManager
import android.os.Build
import android.os.IBinder
import android.util.Log
import android.view.Gravity
import android.view.LayoutInflater
import android.view.WindowManager
import android.widget.TextView
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch

class VoiceAssistantService : Service() {

    private val serviceScope = CoroutineScope(SupervisorJob() + Dispatchers.Main)
    private lateinit var openAIManager: OpenAIManager
    private lateinit var settingsManager: SettingsManager
    private lateinit var windowManager: WindowManager
    private var floatingView: WaveOverlayView? = null
    private var isListening = false
    private var amplitudeJob: kotlinx.coroutines.Job? = null

    private val voiceCommandReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context?, intent: Intent?) {
            Log.d("VoiceAssistant", "Broadcast received: ${intent?.action}")
            when (intent?.action) {
                "com.saic.keyevent.hardkey.report", "android.intent.action.VOICE_COMMAND" -> {
                    // Direksiyon tuşu tetiklemesi
                    val keyCode = intent.getIntExtra("keyCode", -1)
                    if (intent.action == "com.saic.keyevent.hardkey.report" && keyCode != 290) return
                    toggleListening()
                }
                "com.omoda5.voice.ACTION_PLAY_TTS" -> {
                    // Dışarıdan metin okuma talebi
                    val text = intent.getStringExtra("text")
                    if (!text.isNullOrBlank()) {
                        openAIManager.playTextViaTTS(text, serviceScope)
                    }
                }
            }
        }
    }

    override fun onCreate() {
        super.onCreate()
        settingsManager = SettingsManager(this)
        windowManager = getSystemService(WINDOW_SERVICE) as WindowManager

        openAIManager = OpenAIManager(this, onStateChanged = { state ->
            updateFloatingUiState(state)
        }, onResultCallback = { text ->
            if (settingsManager.isSttBroadcastEnabled) {
                val intent = Intent("com.omoda5.voice.ACTION_STT_RESULT")
                intent.putExtra("text", text)
                sendBroadcast(intent)
            }
        })

        val filter = IntentFilter().apply {
            addAction("com.saic.keyevent.hardkey.report")
            addAction("android.intent.action.VOICE_COMMAND")
            addAction("com.omoda5.voice.ACTION_PLAY_TTS")
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            registerReceiver(voiceCommandReceiver, filter, Context.RECEIVER_EXPORTED)
        } else {
            registerReceiver(voiceCommandReceiver, filter)
        }
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        Log.d("VoiceAssistant", "Service Started")
        return START_STICKY
    }

    private fun toggleListening() {
        if (isListening) {
            // İkinci kez basıldı: kaydı durdur ve İŞLE
            isListening = false
            stopAmplitudePolling()
            floatingView?.updateAmplitude(0)
            openAIManager.stopRecordingAndProcess(serviceScope)
        } else if (floatingView != null) {
            // Ekranda yüzen UI var (demek ki işleniyor veya cevap bekleniyor). 
            // Tuşa basılırsa komple İPTAL ET
            openAIManager.cancelRecording()
            removeFloatingUi()
        } else {
            // İlk basış: Kaydı başlat
            isListening = true
            pauseMusic()
            showFloatingUi()
            openAIManager.startRecording()
            startAmplitudePolling()
        }
    }

    private fun startAmplitudePolling() {
        amplitudeJob?.cancel()
        amplitudeJob = serviceScope.launch {
            while (isListening) {
                val amplitude = openAIManager.getMaxAmplitude()
                floatingView?.updateAmplitude(amplitude)
                kotlinx.coroutines.delay(50)
            }
        }
    }

    private fun stopAmplitudePolling() {
        amplitudeJob?.cancel()
        amplitudeJob = null
    }

    private fun pauseMusic() {
        val audioManager = getSystemService(Context.AUDIO_SERVICE) as AudioManager
        // Android O+ AudioManager Focus Request (optional depending on system, but good practice)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val focusRequest = android.media.AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT_EXCLUSIVE)
                .setOnAudioFocusChangeListener { }
                .build()
            audioManager.requestAudioFocus(focusRequest)
        } else {
            @Suppress("DEPRECATION")
            audioManager.requestAudioFocus({ }, AudioManager.STREAM_MUSIC, AudioManager.AUDIOFOCUS_GAIN_TRANSIENT_EXCLUSIVE)
        }

        // Gösterim amacıyla Media_Pause olayı simüle et
        val eventDown = android.view.KeyEvent(android.view.KeyEvent.ACTION_DOWN, android.view.KeyEvent.KEYCODE_MEDIA_PAUSE)
        val eventUp = android.view.KeyEvent(android.view.KeyEvent.ACTION_UP, android.view.KeyEvent.KEYCODE_MEDIA_PAUSE)
        audioManager.dispatchMediaKeyEvent(eventDown)
        audioManager.dispatchMediaKeyEvent(eventUp)
    }

    private fun resumeMusic() {
        val audioManager = getSystemService(Context.AUDIO_SERVICE) as AudioManager
        val eventDown = android.view.KeyEvent(android.view.KeyEvent.ACTION_DOWN, android.view.KeyEvent.KEYCODE_MEDIA_PLAY)
        val eventUp = android.view.KeyEvent(android.view.KeyEvent.ACTION_UP, android.view.KeyEvent.KEYCODE_MEDIA_PLAY)
        audioManager.dispatchMediaKeyEvent(eventDown)
        audioManager.dispatchMediaKeyEvent(eventUp)

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            // Drop focus allowing other apps to play
            audioManager.abandonAudioFocusRequest(
                android.media.AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT_EXCLUSIVE).build()
            )
        } else {
            @Suppress("DEPRECATION")
            audioManager.abandonAudioFocus { }
        }
    }

    private fun showFloatingUi() {
        if (!settingsManager.isFloatingUiEnabled) return
        if (floatingView != null) return

        try {
            val metrics = resources.displayMetrics
            val widthPx = (300 * metrics.density).toInt()
            val heightPx = (150 * metrics.density).toInt()

            val params = WindowManager.LayoutParams(
                widthPx,
                heightPx,
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O)
                    WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY
                else
                    @Suppress("DEPRECATION") WindowManager.LayoutParams.TYPE_PHONE,
                WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,
                android.graphics.PixelFormat.TRANSLUCENT
            ).apply {
                gravity = android.view.Gravity.CENTER_HORIZONTAL or android.view.Gravity.BOTTOM
                y = 100 // Bottom margin
            }

            val view = WaveOverlayView(this).apply {
                setBackgroundColor(android.graphics.Color.parseColor("#CC000000"))
            }
            floatingView = view
            windowManager.addView(floatingView, params)
        } catch (e: Exception) {
            e.printStackTrace()
        }
    }

    private var closeJob: kotlinx.coroutines.Job? = null

    private fun updateFloatingUiState(state: String) {
        if (state.startsWith("HAZIR")) {
            floatingView?.setStateText("Hazır", false)
            closeJob?.cancel()
            closeJob = serviceScope.launch {
                kotlinx.coroutines.delay(2000)
                removeFloatingUi()
                resumeMusic()
            }
        } else {
            closeJob?.cancel()
            val listening = state.contains("DİNLENİYOR")
            floatingView?.setStateText(state, listening)
        }
    }

    private fun removeFloatingUi() {
        if (floatingView != null) {
            try {
                windowManager.removeView(floatingView)
            } catch (e: Exception) {}
            floatingView = null
        }
    }

    override fun onDestroy() {
        super.onDestroy()
        unregisterReceiver(voiceCommandReceiver)
        stopAmplitudePolling()
        removeFloatingUi()
        openAIManager.release()
        serviceScope.cancel()
    }

    override fun onBind(intent: Intent?): IBinder? = null
}

package com.omoda5.demo

import android.content.Intent
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.core.content.ContextCompat

class MainActivity : ComponentActivity() {
    private lateinit var settingsManager: SettingsManager

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        settingsManager = SettingsManager(this)

        // Arka plan servisini hemen başlat
        val serviceIntent = Intent(this, VoiceAssistantService::class.java)
        ContextCompat.startForegroundService(this, serviceIntent)

        setContent {
            MaterialTheme(colorScheme = darkColorScheme()) {
                Surface(modifier = Modifier.fillMaxSize(), color = Color(0xFF1E1E1E)) {
                    SettingsScreen()
                }
            }
        }
    }

    @Composable
    fun SettingsScreen() {
        var mode by remember { 
            mutableStateOf(if (settingsManager.sttEngine == "HERMES") "HERMES" else "LOKAL") 
        }

        Column(modifier = Modifier.fillMaxSize().padding(16.dp), horizontalAlignment = Alignment.CenterHorizontally) {
            Spacer(modifier = Modifier.height(60.dp))
            Text("OMODA ASİSTAN", color = Color.White, fontSize = 28.sp, fontWeight = FontWeight.Bold)
            Spacer(modifier = Modifier.height(40.dp))

