package com.omoda5.demo

import android.content.Context
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.graphics.RectF
import android.util.AttributeSet
import android.view.View

class WaveOverlayView @JvmOverloads constructor(
    context: Context, attrs: AttributeSet? = null, defStyleAttr: Int = 0
) : View(context, attrs, defStyleAttr) {

    private val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
        color = Color.GREEN
        style = Paint.Style.FILL
    }

    private val textPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
        color = Color.GREEN
        textSize = 48f
        textAlign = Paint.Align.CENTER
    }

    private val maxBars = 15
    private val amplitudes = FloatArray(maxBars)
    private var textToDisplay = "🎙️ Dinleniyor..."
    private var isListening = false

    fun updateAmplitude(amplitude: Int) {
        // Shift amplitudes
        for (i in 0 until maxBars - 1) {
            amplitudes[i] = amplitudes[i + 1]
        }

        // Normalize amplitude to a 0.0 - 1.0 range (MediaRecorder max is ~32767)
        val normalized = (amplitude / 32767f).coerceIn(0f, 1f)

        // Boost low volumes a bit for better visual effect, and add a minimum height
        val boosted = Math.pow(normalized.toDouble(), 0.5).toFloat() * 0.8f + 0.1f
        amplitudes[maxBars - 1] = if (isListening) boosted else 0f

        invalidate()
    }

    fun setStateText(text: String, listening: Boolean) {
        textToDisplay = text
        isListening = listening
        if (!listening) {
            for (i in amplitudes.indices) {
                amplitudes[i] = 0f
            }
        }
        invalidate()
    }

    override fun onDraw(canvas: Canvas) {
        super.onDraw(canvas)

        val width = width.toFloat()
        val height = height.toFloat()

        // Draw text
        val textY = height - 40f
        canvas.drawText(textToDisplay, width / 2f, textY, textPaint)

        // Draw wave bars
        if (isListening) {
            val barWidth = width / (maxBars * 2)
            val spacing = barWidth
            val maxBarHeight = height - 100f // leave room for text
            val startX = (width - (maxBars * (barWidth + spacing) - spacing)) / 2f

            for (i in 0 until maxBars) {
                val barHeight = amplitudes[i] * maxBarHeight
                val rect = RectF(
                    startX + i * (barWidth + spacing),
                    (maxBarHeight - barHeight) / 2f + 20f,
                    startX + i * (barWidth + spacing) + barWidth,
                    (maxBarHeight + barHeight) / 2f + 20f
                )
                // Draw rounded rect
                canvas.drawRoundRect(rect, barWidth / 2f, barWidth / 2f, paint)
            }
        }
    }
}

