// Yeni event eklemek için ilgili sealed class'a branch ekle
// =============================================================

// ─── Ana event ağacı ─────────────────────────────────────────

sealed class Event {

    // Araç telemetri eventleri — VehicleLayer tarafından üretilir
    sealed class VehicleEvent : Event() {
        data class StateUpdated(val state: VehicleState) : VehicleEvent()
        data class SpeedChanged(val speed: Float) : VehicleEvent()
        data class GearChanged(val gear: String) : VehicleEvent()
        data class DoorStateChanged(val open: Boolean) : VehicleEvent()
        object LowFuel : VehicleEvent()
        object TirePressureLow : VehicleEvent()
        object EngineTemperatureHigh : VehicleEvent()
    }

    // Ses asistan eventleri — VoiceAssistantService tarafından üretilir
    sealed class VoiceEvent : Event() {
        object RecordingStarted : VoiceEvent()
        object RecordingStopped : VoiceEvent()
        object RecordingCancelled : VoiceEvent()
        data class SttResult(val text: String, val engine: SttEngine) : VoiceEvent()
    }

    // Yapay zekâ eventleri — OpenAIManager (ai-hermes) tarafından üretilir
    sealed class AIEvent : Event() {
        data class ResponseReceived(val text: String) : AIEvent()
        data class TTSStarted(val text: String) : AIEvent()
        object TTSCompleted : AIEvent()
        data class Error(val message: String) : AIEvent()
    }

    // Ses motor eventleri — AudioEngine tarafından üretilir
    sealed class AudioEvent : Event() {
        data class FocusChanged(val lane: AudioLane, val gained: Boolean) : AudioEvent()
        data class DuckingApplied(val level: Float) : AudioEvent()
        object MusicPaused : AudioEvent()
        object MusicResumed : AudioEvent()
    }

    // UI eventleri — overlay ve Compose katmanına yöneliktir
    sealed class UIEvent : Event() {
        data class StateTextChanged(val text: String, val isListening: Boolean) : UIEvent()
        object OverlayShow : UIEvent()
        object OverlayHide : UIEvent()
        data class DrivingSummaryReady(val summary: DrivingSummary) : UIEvent()
    }

    // Sistem seviyesi eventler
    sealed class SystemEvent : Event() {
        data class HardKeyPressed(val keyCode: Int) : SystemEvent()
        data class ProfileChanged(val profile: AssistantProfile) : SystemEvent()
        data class ContextChanged(val context: DrivingContext) : SystemEvent()
    }

    // Uyarı eventleri — AlertEngine tarafından üretilir
    sealed class AlertEvent : Event() {
        data class Triggered(val alert: Alert) : AlertEvent()
        data class Dismissed(val alertId: String) : AlertEvent()
    }

    // Komut yönlendirme eventleri — CommandRouter tarafından üretilir
    sealed class CommandEvent : Event() {
