enum class DrivingContext {
    PARKED,     // Hız ≈ 0, vites P veya el freni
    CITY,       // 25–80 km/h
    HIGHWAY,    // 80+ km/h
    TRAFFIC,    // 1–25 km/h, vites P değil
    RISK,       // Hareket halinde kapı açık / kritik durum
    UNKNOWN     // Başlangıç durumu
}

