    LOCAL,      // Android native TextToSpeech
    EDGE        // Microsoft Edge TTS (ağ gerektirir)
}

// ─── Komut yönlendirme hedefleri ──────────────────────────────

enum class CommandTarget {
    VEHICLE_ENGINE,     // Araç kontrol komutları — LLM kullanılmaz, kural tabanlı
    HOME_ASSISTANT,     // Ev otomasyonu komutları (HA webhook/API)
    HERMES_AI,          // Bilgi, sohbet, genel sorular → OpenAIManager
    UNKNOWN             // Tanınamayan komut
}

// ─── Uyarı veri modeli ────────────────────────────────────────

data class Alert(
    val id: String,
    val priority: AlertPriority,
    val message: String,
    val repeatable: Boolean = false,     // Tekrar edilebilir uyarı mı?
    val timestamp: Long = System.currentTimeMillis()
)

// Uyarı öncelik seviyeleri — PDF'deki 4 seviye
enum class AlertPriority {
    CRITICAL,       // Seviye 1: Motor arızası, kapı açık, lastik basıncı, aşırı sıcaklık — her zaman okunur
    IMPORTANT,      // Seviye 2: Trafik gecikmesi, kuvvetli yağış, fırtına, afet bildirimi — kurala bağlı
    INFORMATIONAL,  // Seviye 3: Takvim, haber, hava özeti — kullanıcı tercihine bağlı
    CONVERSATION    // Seviye 4: Yalnızca kullanıcı talep ettiğinde
}

// ─── Sürüş analizi veri modeli ────────────────────────────────

data class DrivingSummary(
    val durationMinutes: Int = 0,
    val distanceKm: Float = 0f,
    val averageSpeedKmh: Float = 0f,
    val maxSpeedKmh: Float = 0f,
    val hardBrakeCount: Int = 0,
    val averageFuelConsumption: Float = 0f,   // lt/100km tahmini
    val isEconomical: Boolean = false
)

