package com.omoda5.assistant.core

import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.filterIsInstance

// =============================================================
// EventBus.kt — Sistem genelinde tek iletişim noktası
// Tüm modüller (vehicle, audio, ai-hermes, overlay) bu bus üzerinden konuşur
// SharedFlow: replay=0 → geçmiş event'ler yeni subscriber'a gönderilmez
// extraBufferCapacity=64 → ani burst'lerde kayıp olmaz
// =============================================================

object EventBus {

    private val _events = MutableSharedFlow<Event>(
        replay = 0,
        extraBufferCapacity = 64
    )

    // Dışarıdan yalnızca dinleme — yazma sadece emit() ile
    val events: SharedFlow<Event> = _events.asSharedFlow()

    // Blocking olmayan gönderim — buffer doluysa false döner
    fun emit(event: Event): Boolean {
        return _events.tryEmit(event)
    }

    // Suspend gönderim — coroutine içinden, buffer doluysa bekler
    suspend fun emitSuspend(event: Event) {
        _events.emit(event)
    }

    // Tip güvenli filtreli dinleme — inline reified ile kullanım kolaylığı
    // Örnek: EventBus.on<Event.VehicleEvent.StateUpdated>().collect { ... }
    inline fun <reified T : Event> on(): kotlinx.coroutines.flow.Flow<T> {
        return events.filterIsInstance<T>()
    }
}

