package com.omoda5.assistant.core

import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch

// =============================================================
// ContextEngine.kt — VehicleState → DrivingContext dönüşümü
// Araç telemetrisini yorumlayarak sürüş bağlamını belirler
// Bağlam değiştiğinde SystemEvent.ContextChanged yayınlar
// PolicyEngine ve AlertEngine bu bağlamı tüketir
// =============================================================

class ContextEngine {

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)

    // Son bilinen araç durumu
    private var lastState = VehicleState()

    // Mevcut sürüş bağlamı — dışarıdan okunabilir, değiştirilemez
    var currentContext: DrivingContext = DrivingContext.UNKNOWN
        private set

    init {
        observeVehicleState()
    }

    // VehicleEvent.StateUpdated dinle → bağlamı güncelle
    private fun observeVehicleState() {
        scope.launch {
            EventBus.on<Event.VehicleEvent.StateUpdated>().collect { event ->
                lastState = event.state
                val newContext = inferContext(event.state)

                // Sadece değiştiğinde event yayınla — gereksiz event üretme
                if (newContext != currentContext) {
                    currentContext = newContext
                    EventBus.emit(Event.SystemEvent.ContextChanged(newContext))
                }
            }
        }
    }

    // Araç durumundan bağlam çıkarımı
    // Kural sırası önemlidir — RISK her zaman önce kontrol edilir
    private fun inferContext(state: VehicleState): DrivingContext {
        return when {

            // Kritik durum: hareket halinde kapı açık
            state.speed > 5f && state.doorOpen ->
                DrivingContext.RISK

            // Kritik durum: aşırı motor sıcaklığı
            state.engineTemp > 105f ->
                DrivingContext.RISK

            // Park: hız sıfıra yakın VE (vites P VEYA el freni çekili)
            state.speed < 2f && (state.gear == "P" || state.parkingBrake) ->
                DrivingContext.PARKED

            // Trafik: düşük hız, hareket halinde
            state.speed in 1f..25f && state.gear != "P" ->
                DrivingContext.TRAFFIC

            // Şehir içi
            state.speed in 25f..80f ->
                DrivingContext.CITY

            // Otoyol / yüksek hız
            state.speed > 80f ->
                DrivingContext.HIGHWAY

            else -> DrivingContext.UNKNOWN
        }
    }

    // Son bilinen bağlamı döndür
    fun getContext(): DrivingContext = currentContext

    // Son araç durumunu döndür
    fun getLastState(): VehicleState = lastState

    fun release() {
        scope.cancel()
    }
}

