//   "hava nasıl"              → HERMES_AI
// =============================================================

class CommandRouter {

    // Araç kontrol anahtar kelimeleri — LLM kullanılmaz, kural tabanlı
    private val vehicleKeywords = listOf(
        "klima", "ısıtma", "soğutma", "fan", "havalandırma",
        "pencere", "cam", "rezistans",
        "müzik", "ses", "radyo", "çal", "durdur", "atla", "ileri", "geri",
        "telefon", "ara", "kapat çağrı",
        "navigasyon", "git", "yol tarifi",
        "koltuk", "ayna",
        "park", "fren",
        "farlar", "dörtlü", "sinyal",
        "kapı", "bagaj",
        "motor"
    )

    // Home Assistant anahtar kelimeleri
    private val homeAssistantKeywords = listOf(
        "ev", "evde", "eve",
        "salon", "mutfak", "yatak odası", "banyo", "çalışma odası",
        "ışık", "lamba", "aydınlatma",
        "perde", "panjur", "stor",
        "kapı zili", "alarm", "güvenlik",
        "termostat", "kombi", "kalorifer",
        "prize", "priz",
        "tv", "televizyon"
    )

    // Hermes AI anahtar kelimeleri (genel bilgi / sohbet)
    private val hermesKeywords = listOf(
        "hava", "hava durumu", "yağmur", "kar", "fırtına",
        "trafik", "yol", "kaza", "yoğunluk",
        "nedir", "nasıl", "nerede", "ne zaman", "kim", "neden",
        "anlat", "açıkla", "söyle", "bilgi",
        "takvim", "toplantı", "hatırlatma",
        "haber", "gündem",
        "hesapla", "çevir", "kaç"
    )

    // STT metnini analiz ederek yönlendirme kararı üretir
    // EventBus'a CommandEvent.RouteDecided yayınlar
    fun route(text: String): CommandTarget {
        val lower = text.lowercase().trim()

        val target = when {
            matchesAny(lower, vehicleKeywords) -> CommandTarget.VEHICLE_ENGINE
            matchesAny(lower, homeAssistantKeywords) -> CommandTarget.HOME_ASSISTANT
            matchesAny(lower, hermesKeywords) -> CommandTarget.HERMES_AI
            else -> CommandTarget.UNKNOWN
        }

        // Yönlendirme kararını sisteme bildir
        EventBus.emit(Event.CommandEvent.RouteDecided(text = text, target = target))

        return target
    }

    // Metinde anahtar kelimelerden herhangi biri geçiyor mu?
    private fun matchesAny(text: String, keywords: List<String>): Boolean {
        return keywords.any { text.contains(it) }
    }

    // Araç komutu mu? — dışarıdan hızlı kontrol için
    fun isVehicleCommand(text: String): Boolean =
        route(text) == CommandTarget.VEHICLE_ENGINE

    // HA komutu mu?
    fun isHomeAssistantCommand(text: String): Boolean =
        route(text) == CommandTarget.HOME_ASSISTANT

    // Hermes'e gidecek mi?
    fun isHermesCommand(text: String): Boolean =
        route(text) == CommandTarget.HERMES_AI
}

