package com.omoda5.assistant.core

// =============================================================
// PolicyEngine.kt — Güvenlik kuralları ve komut izin kontrolü
// Hangi bağlamda hangi komutların çalışabileceğine karar verir
// ContextEngine'den aldığı bağlama göre kuralları uygular
//
// PDF güvenlik kuralları:
//   Araç hareket halindeyken değiştirilemez:
//     - Güvenlik eşikleri
//     - Trafik/afet bildirimleri
//     - Kritik ses seviyeleri
//   Araç dururken (sesli): ses tonu, konuşma hızı, Hermes açık/kapalı
// =============================================================

class PolicyEngine(
    private val contextEngine: ContextEngine,
    private val profileManager: ProfileManager
) {

    // Mevcut bağlamda komut çalıştırılabilir mi?
    fun canExecute(target: CommandTarget, text: String): PolicyResult {
        val context = contextEngine.currentContext
        val profile = profileManager.currentProfile
        val state = contextEngine.getLastState()

        return when {

            // RISK modunda yalnızca güvenlik komutları geçer
            context == DrivingContext.RISK ->
                if (target == CommandTarget.VEHICLE_ENGINE && isSafetyCommand(text))
                    PolicyResult.ALLOWED
                else
                    PolicyResult.BLOCKED_SAFETY("Araç risk durumunda — yalnızca güvenlik komutları")

            // SILENT profilde yalnızca CRITICAL uyarılar geçer
            profile == AssistantProfile.SILENT ->
                if (target == CommandTarget.VEHICLE_ENGINE && isSafetyCommand(text))
                    PolicyResult.ALLOWED
                else
                    PolicyResult.BLOCKED_PROFILE("Sessiz mod aktif")

            // MINIMAL profilde Hermes AI devre dışı
            profile == AssistantProfile.MINIMAL && target == CommandTarget.HERMES_AI ->
                PolicyResult.BLOCKED_PROFILE("Minimal modda AI devre dışı")

            // Otoyolda uzun Hermes AI sohbeti kısıtlanır
            context == DrivingContext.HIGHWAY && target == CommandTarget.HERMES_AI ->
                if (isSimpleQuery(text))
                    PolicyResult.ALLOWED
                else
                    PolicyResult.BLOCKED_SAFETY("Otoyolda karmaşık AI sorgusu kısıtlandı")

            // Yüksek hızda ayar değişikliği engelle (> 80 km/h)
            state.speed > 80f && isSettingsChange(text) ->
                PolicyResult.BLOCKED_SAFETY("Seyir halinde ayar değiştirilemez")

            // Diğer durumlarda serbest
            else -> PolicyResult.ALLOWED
        }
    }

    // Uyarı gösterilmeli mi? — profil ve bağlama göre filtrele
    fun shouldShowAlert(priority: AlertPriority): Boolean {
        val profile = profileManager.currentProfile
        return when (priority) {
            // Kritik uyarılar her zaman gösterilir
            AlertPriority.CRITICAL -> true

            // Önemli uyarılar: MINIMAL ve SILENT profilde gösterilmez
            AlertPriority.IMPORTANT ->
                profile == AssistantProfile.NORMAL || profile == AssistantProfile.ASSISTANT

            // Bilgilendirici: sadece ASSISTANT profilde
            AlertPriority.INFORMATIONAL ->
                profile == AssistantProfile.ASSISTANT

            // Sohbet seviyesi: asla otomatik
            AlertPriority.CONVERSATION -> false
        }
    }

    // Güvenlikle ilgili komut mu? (araç komutlarında her zaman izin verilir)
    private fun isSafetyCommand(text: String): Boolean {
        val safetyWords = listOf("dur", "park", "fren", "telefon", "ara", "acil")
        return safetyWords.any { text.lowercase().contains(it) }
    }

    // Basit sorgu mu? (tek kelime / kısa soru)
    private fun isSimpleQuery(text: String): Boolean {
        return text.split(" ").size <= 4
    }

    // Ayar değişikliği komutu mu?
    private fun isSettingsChange(text: String): Boolean {
        val settingsWords = listOf("ayar", "profil", "mod", "değiştir", "aç kapat")
        return settingsWords.any { text.lowercase().contains(it) }
    }
}

// Politika sonucu
sealed class PolicyResult {
    object ALLOWED : PolicyResult()
    data class BLOCKED_SAFETY(val reason: String) : PolicyResult()
    data class BLOCKED_PROFILE(val reason: String) : PolicyResult()

    val isAllowed: Boolean get() = this is ALLOWED
    val blockedReason: String? get() = when (this) {
        is BLOCKED_SAFETY -> reason
        is BLOCKED_PROFILE -> reason
        else -> null
    }
}

