import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch
import java.util.UUID

// =============================================================
// AlertEngine.kt — Olay ve uyarı motoru
// Araç sensörlerinden gelen event'leri izler, koşul oluşunca
// öncelikli Alert üretir ve EventBus'a yayınlar
//
// PDF'deki uyarı kuralları:
//   Kapı açık (hareket halinde)     → CRITICAL
//   Lastik basıncı düşük            → CRITICAL
//   Motor arızası / sıcaklık yüksek → CRITICAL
//   Yakıt azaldı (< %15)            → IMPORTANT
//   Trafik gecikmesi > %40          → IMPORTANT
// =============================================================

class AlertEngine(
    private val policyEngine: PolicyEngine
) {

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)

    // Aktif uyarı ID'leri — aynı uyarıyı tekrar üretmemek için
    private val activeAlerts = mutableSetOf<String>()

    init {
        observeVehicleEvents()
        observeContextEvents()
    }

    // Araç event'lerini izle → uyarı koşulu varsa tetikle
    private fun observeVehicleEvents() {
        scope.launch {
            EventBus.on<Event.VehicleEvent>().collect { event ->
                when (event) {

                    // Kapı açık uyarısı — CRITICAL
                    is Event.VehicleEvent.DoorStateChanged -> {
                        if (event.open) {
                            triggerAlert(
                                id = "DOOR_OPEN",
                                priority = AlertPriority.CRITICAL,
                                message = "Kapı açık!"
                            )
                        } else {
                            dismissAlert("DOOR_OPEN")
                        }
                    }

                    // Düşük yakıt uyarısı — IMPORTANT
                    is Event.VehicleEvent.LowFuel -> {
                        triggerAlert(
                            id = "LOW_FUEL",
                            priority = AlertPriority.IMPORTANT,
                            message = "Yakıt seviyesi düşük. En yakın istasyonu bulayım mı?"
                        )
                    }

                    // Lastik basıncı düşük — CRITICAL
                    is Event.VehicleEvent.TirePressureLow -> {
                        triggerAlert(
                            id = "TPMS_LOW",
                            priority = AlertPriority.CRITICAL,
                            message = "Lastik basıncı düşük! Lütfen durdurun."
                        )
                    }

                    // Motor sıcaklığı yüksek — CRITICAL
                    is Event.VehicleEvent.EngineTemperatureHigh -> {
                        triggerAlert(
                            id = "ENGINE_TEMP_HIGH",
                            priority = AlertPriority.CRITICAL,
                            message = "Motor sıcaklığı kritik seviyede! Aracı durdurun."
                        )
                    }

                    // VehicleState güncellemesi — anlık koşul kontrolü
                    is Event.VehicleEvent.StateUpdated -> {
                        checkStateTriggers(event.state)
                    }

                    else -> Unit
                }
            }
        }
    }

    // Bağlam değişikliğini izle — RISK modunda ek uyarı
    private fun observeContextEvents() {
        scope.launch {
            EventBus.on<Event.SystemEvent.ContextChanged>().collect { event ->
                if (event.context == DrivingContext.RISK) {
                    triggerAlert(
                        id = "RISK_CONTEXT",
                        priority = AlertPriority.CRITICAL,
                        message = "Dikkat! Tehlikeli sürüş durumu algılandı."
                    )
                } else {
                    dismissAlert("RISK_CONTEXT")
                }
            }
        }
    }

    // VehicleState üzerinde eşik kontrolü
    private fun checkStateTriggers(state: VehicleState) {
        // Yakıt %15 altına düştüyse
        if (state.fuelLevel < 0.15f && !activeAlerts.contains("LOW_FUEL")) {
            triggerAlert(
                id = "LOW_FUEL",
                priority = AlertPriority.IMPORTANT,
                message = "Yakıt azalıyor, %${(state.fuelLevel * 100).toInt()} kaldı."
            )
        } else if (state.fuelLevel >= 0.15f) {
            dismissAlert("LOW_FUEL")
        }

        // Motor sıcaklığı eşik kontrolü
        if (state.engineTemp > 105f && !activeAlerts.contains("ENGINE_TEMP_HIGH")) {
            EventBus.emit(Event.VehicleEvent.EngineTemperatureHigh)
        }
    }

    // Uyarı üret — PolicyEngine'e danış, izin varsa yayınla
    private fun triggerAlert(id: String, priority: AlertPriority, message: String) {
        if (activeAlerts.contains(id)) return  // Aynı uyarı zaten aktif
        if (!policyEngine.shouldShowAlert(priority)) return  // Profil engelliyor

        val alert = Alert(
            id = id,
            priority = priority,
            message = message
        )
        activeAlerts.add(id)
        EventBus.emit(Event.AlertEvent.Triggered(alert))
    }

    // Uyarıyı kaldır
    fun dismissAlert(id: String) {
        if (activeAlerts.remove(id)) {
            EventBus.emit(Event.AlertEvent.Dismissed(id))
        }
    }

    // Dış kaynaklı uyarı (trafik, hava, HA) — servis katmanından çağrılır
    fun triggerExternalAlert(message: String, priority: AlertPriority) {
        val id = "EXT_${UUID.randomUUID()}"
        triggerAlert(id = id, priority = priority, message = message)
    }

    fun release() {
        scope.cancel()
    }
}
