package com.omoda5.assistant.core

import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch

// =============================================================
// DrivingAnalyzer.kt — Sürüş sırasında veri toplar, bitiş koşulu
// oluşunca analiz raporu üretir
//
// Tetikleyici (PDF'e göre):
//   Hız = 0 VE Vites = P VE sürüş süresi > 1 dakika
//
// Örnek çıktı:
//   "Bugünkü sürüşünüzde 3 kez ani fren yaptınız."
//   "Ortalama yakıt tüketiminiz 6.4 litre oldu."
//   "Ekonomik sürüş ortalamasının üzerindeydi."
// =============================================================

class DrivingAnalyzer {

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)

    // Sürüş başlangıç zamanı
    private var tripStartTime: Long = 0L

    // Anlık veri toplayıcılar
    private var speedSamples = mutableListOf<Float>()
    private var lastSpeed = 0f
    private var maxSpeed = 0f
    private var hardBrakeCount = 0
    private var isTripActive = false

    // Ani fren tespiti için son hız örneği
    private var lastSpeedSample = 0f

    init {
        observeVehicleState()
        observeContextChanges()
    }

    // VehicleState güncellemelerini dinle — veri topla
    private fun observeVehicleState() {
        scope.launch {
            EventBus.on<Event.VehicleEvent.StateUpdated>().collect { event ->
                val state = event.state

                // Sürüş başlangıcı: hız > 5 ve önceden aktif değil
                if (!isTripActive && state.speed > 5f) {
                    startTrip()
                }

                if (isTripActive) {
                    collectSample(state)
                }

                lastSpeed = state.speed
            }
        }
    }

    // Bağlam değişikliğini izle — PARKED → sürüş bitti
    private fun observeContextChanges() {
        scope.launch {
            EventBus.on<Event.SystemEvent.ContextChanged>().collect { event ->
                // Park konumuna geçiş: sürüş bitti
                if (event.context == DrivingContext.PARKED && isTripActive) {
                    val durationMs = System.currentTimeMillis() - tripStartTime
                    // 1 dakikadan kısa sürüşleri analiz etme
                    if (durationMs > 60_000L) {
                        val summary = generateSummary(durationMs)
                        EventBus.emit(Event.UIEvent.DrivingSummaryReady(summary))
                    }
                    resetTrip()
                }
            }
        }
    }

    // Sürüş başlat
    private fun startTrip() {
        isTripActive = true
        tripStartTime = System.currentTimeMillis()
        speedSamples.clear()
        hardBrakeCount = 0
        maxSpeed = 0f
        lastSpeedSample = 0f
    }

    // Anlık veri örnekle
    private fun collectSample(state: VehicleState) {
        speedSamples.add(state.speed)

        // Maksimum hız takibi
        if (state.speed > maxSpeed) maxSpeed = state.speed

        // Ani fren tespiti: 2 saniyede 20+ km/h düşüş
        // (polling aralığı ~1-2s olduğundan bu yaklaşık hesaptır)
        val speedDelta = lastSpeedSample - state.speed
        if (speedDelta > 20f) {
            hardBrakeCount++
        }
        lastSpeedSample = state.speed
    }

    // Sürüş özeti oluştur
    private fun generateSummary(durationMs: Long): DrivingSummary {
        val durationMin = (durationMs / 60_000L).toInt()
        val avgSpeed = if (speedSamples.isNotEmpty()) speedSamples.average().toFloat() else 0f

        // Basit yakıt tüketimi tahmini (şehir: 8.5 lt/100, otoyol: 6.0 lt/100)
        val estimatedConsumption = when {
            avgSpeed > 80f -> 6.0f + (hardBrakeCount * 0.3f)
            avgSpeed > 40f -> 7.5f + (hardBrakeCount * 0.4f)
            else -> 9.0f + (hardBrakeCount * 0.5f)
        }

        // Ekonomik sürüş eşiği: ortalama < 7.5 lt/100 ve sert fren < 2
        val isEconomical = estimatedConsumption < 7.5f && hardBrakeCount < 2

        // Yaklaşık mesafe (avg hız × süre)
        val distanceKm = avgSpeed * (durationMs / 3_600_000f)

        return DrivingSummary(
            durationMinutes = durationMin,
            distanceKm = distanceKm,
            averageSpeedKmh = avgSpeed,
            maxSpeedKmh = maxSpeed,
            hardBrakeCount = hardBrakeCount,
            averageFuelConsumption = estimatedConsumption,
            isEconomical = isEconomical
        )
    }

    // Sürüş verilerini sıfırla
    private fun resetTrip() {
        isTripActive = false
        speedSamples.clear()
        hardBrakeCount = 0
        maxSpeed = 0f
        lastSpeedSample = 0f
    }

    fun release() {
        scope.cancel()
    }
}

